def main(src, dst):
    p = Presentation(src)
    for i, s in enumerate(p.slides, 1):
        tf = s.notes_slide.notes_text_frame
        tf.text = NOTES[i]
    p.save(dst)

if __name__ == "__main__":
    main(sys.argv[1], sys.argv[2])
